  id: number;
  description: string;
  vendor: string;
  location: string;
  qtyOnHand: number;
  qtyReserved: number;
  receiveDate: string;
  expiryDate: string | null;
  mslLevel: number;
  status: InventoryLotRowStatus;
}

/** ─── 揀貨波次 / FIFO 配貨 ─── */

